function validate([ribbons, k]) {
  if (!Array.isArray(ribbons) || ribbons.length < 1 || ribbons.length > 100000) return 'ribbons needs 1 to 10^5 lengths.';
  if (ribbons.some(r => !Number.isInteger(r) || r < 1 || r > 100000)) return 'Each ribbon length is between 1 and 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  return null;
}

