function maxLength(ribbons, k) {
  let low = 0;
  let high = Math.max(...ribbons);
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    let pieces = 0;
    for (const ribbon of ribbons) {
      pieces += Math.floor(ribbon / mid);
    }
    if (pieces >= k) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

