function maxLength(ribbons, k) {
  let longest = 0;
  for (const r of ribbons) if (r > longest) longest = r;
  for (let length = longest; length >= 1; length--) {
    let total = 0;
    for (const r of ribbons) total += Math.floor(r / length);
    if (total >= k) return length;
  }
  return 0;
}

