function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.7 ? 2000 : int(1000, 2000)) : int(1, 6);
  const top = large ? (rand() < 0.6 ? 100000 : int(1, 1000)) : (rand() < 0.5 ? 10 : 30);
  const ribbons = Array.from({ length: n }, () => int(1, top));
  let sum = 0;
  for (const r of ribbons) sum += r;
  const roll = rand();
  let k;
  if (roll < 0.15) k = sum + int(1, large ? 1000 : 5);
  else if (roll < 0.3) k = int(1, Math.min(n, 3));
  else if (roll < 0.45) k = sum;
  else k = int(1, Math.max(1, Math.floor(sum / int(1, large ? 100 : 4))));
  if (large && rand() < 0.1) k = 1000000000;
  return [ribbons, Math.min(Math.max(k, 1), 1000000000)];
}
